<?php
session_start();
if (!isset($_SESSION['id']) || $_SESSION['rol'] !== 'admin') { header("Location: ../../views/home.php"); exit(); }
require_once "../../config/conexion.php";
require_once "../../config/csrf.php";
$con = conexion();
$msg = $_GET['msg'] ?? '';
$error = $_GET['error'] ?? '';
$query_sedes = "SELECT s.*, COUNT(DISTINCT p.id) as total_pisos, COUNT(DISTINCT a.id) as total_ambientes, COUNT(DISTINCT CASE WHEN u.rol = 'instructor' THEN u.id END) as total_instructores, COUNT(DISTINCT CASE WHEN u.rol = 'celador' THEN u.id END) as total_celadores, COUNT(DISTINCT CASE WHEN ho.estado IN ('ocupado', 'proximo_a_desocupar') AND DATE(ho.fecha_inicio) = CURDATE() THEN ho.id END) as ocupaciones_activas FROM sedes s LEFT JOIN pisos p ON s.id = p.sede_id LEFT JOIN ambientes a ON p.id = a.piso_id LEFT JOIN usuarios u ON s.id = u.sede_id LEFT JOIN historial_ocupacion ho ON a.id = ho.ambiente_id GROUP BY s.id ORDER BY s.estado DESC, s.nombre ASC";
$result_sedes = mysqli_query($con, $query_sedes);
$nombre_admin = $_SESSION['nombre'];
$total_sedes = $result_sedes ? mysqli_num_rows($result_sedes) : 0;
?>
