<?php if ($error): ?><div class="mensaje-error" role="alert"><i class="bi bi-exclamation-circle-fill"></i><?php echo $error === 'no_eliminar' ? 'No se puede eliminar la sede porque tiene pisos o usuarios asignados.' : ($error === 'campos_vacios' ? 'Completa todos los campos obligatorios.' : 'No fue posible realizar la operación.'); ?></div><?php endif; ?>
<section class="directorio-sedes" aria-labelledby="tituloDirectorio"><div class="directorio-cabecera"><div><h2 id="tituloDirectorio">Directorio de sedes</h2><p><strong id="contadorSedes"><?php echo $total_sedes; ?></strong> sede<?php echo $total_sedes == 1 ? '' : 's'; ?> registrada<?php echo $total_sedes == 1 ? '' : 's'; ?></p></div><label class="buscador"><i class="bi bi-search"></i><input type="search" id="buscarSede" placeholder="Buscar por nombre o ciudad" autocomplete="off"><span class="sr-only">Buscar sede</span></label></div>
<div class="sedes-grid">
<?php if ($result_sedes && $total_sedes > 0): while ($sede = mysqli_fetch_assoc($result_sedes)): ?>
<article class="sede-card <?php echo $sede['estado'] === 'inactiva' ? 'inactiva' : ''; ?>" data-busqueda="<?php echo htmlspecialchars(strtolower($sede['nombre'] . ' ' . $sede['ciudad'])); ?>"><div class="card-cabecera"><div class="sede-icono"><i class="bi bi-building"></i></div><span class="badge <?php echo $sede['estado']; ?>"><i class="bi bi-circle-fill"></i><?php echo $sede['estado'] === 'activa' ? 'Activa' : 'Inactiva'; ?></span></div><div class="sede-info"><h3><?php echo htmlspecialchars($sede['nombre']); ?></h3><p class="sede-ciudad"><i class="bi bi-geo-alt"></i><?php echo htmlspecialchars($sede['ciudad']); ?></p><?php if ($sede['direccion']): ?><p class="sede-direccion"><?php echo htmlspecialchars($sede['direccion']); ?></p><?php endif; ?></div><div class="sede-estadisticas"><div class="stat"><strong><?php echo $sede['total_pisos']; ?></strong><span>Pisos</span></div><div class="stat"><strong><?php echo $sede['total_ambientes']; ?></strong><span>Ambientes</span></div><div class="stat"><strong><?php echo $sede['total_instructores']; ?></strong><span>Instructores</span></div><div class="stat"><strong><?php echo $sede['total_celadores']; ?></strong><span>Celadores</span></div></div><?php if ($sede['ocupaciones_activas'] > 0): ?><p class="sede-alerta"><i class="bi bi-activity"></i><?php echo $sede['ocupaciones_activas']; ?> ocupación(es) activa(s) hoy</p><?php endif; ?><div class="sede-acciones"><?php if ($sede['estado'] === 'activa'): ?><a href="dashboard_admin.php?sede_id=<?php echo $sede['id']; ?>" class="btn-ingresar">Ingresar <i class="bi bi-arrow-right"></i></a><?php endif; ?><button class="btn-editar" type="button" onclick="editarSede(<?php echo $sede['id']; ?>)" title="Editar" aria-label="Editar sede"><i class="bi bi-pencil"></i></button><button class="btn-eliminar" type="button" onclick='confirmarEliminar(<?php echo $sede['id']; ?>, <?php echo json_encode($sede['nombre']); ?>)' title="Eliminar" aria-label="Eliminar sede"><i class="bi bi-trash3"></i></button></div></article>
<?php endwhile; else: ?><div class="estado-vacio"><div class="vacio-icono"><i class="bi bi-buildings"></i></div><h3>Aún no hay sedes registradas</h3><p>Crea la primera sede para comenzar a gestionar sus ambientes.</p><button class="btn-crear-primera" id="btnPrimeraSede" type="button"><i class="bi bi-plus-lg"></i> Crear primera sede</button></div><?php endif; ?>
</div><div class="sin-resultados" id="sinResultados" hidden><i class="bi bi-search"></i><h3>No encontramos sedes</h3><p>Intenta con otro nombre o ciudad.</p></div></section></main>
